        .replace(' ', "_");
    match normalised.as_str() {
        "billing_question" => Intent::BillingQuestion,
        "technical_support" => Intent::TechnicalSupport,
        "account_change" => Intent::AccountChange,
        "general_inquiry" => Intent::GeneralInquiry,
        _ => Intent::Unknown,
    }
}

fn parse_reply(reply: &str, fallback_question: &str) -> (Intent, Vec<String>, String) {
    let mut intent = Intent::Unknown;
    let mut question: Option<String> = None;
    let mut entities: Vec<String> = Vec::new();

    for line in reply.lines() {
        let Some((key, value)) = line.split_once(':') else {
            continue;
        };
        let value = value.trim();
        match key.trim().to_ascii_lowercase().as_str() {
            "intent" => intent = parse_intent(value),
            "question" if question.is_none() && !value.is_empty() => {
                question = Some(value.to_string());
            }
            "entities" => {
                entities = value
                    .split(',')
                    .map(str::trim)
                    .filter(|e| !e.is_empty())
                    .take(ENTITY_MAX_COUNT)
                    .map(|e| truncate_chars(e, ENTITY_MAX_CHARS))
                    .collect();
            }
            _ => {}
        }
    }

    // The ensures bound is enforced here, not trusted from the model.
    let question_source = question.unwrap_or_else(|| fallback_question.to_string());
    let question = truncate_chars(&question_source, QUESTION_MAX_CHARS);

    (intent, entities, question)
}

struct Node;

impl Guest for Node {
    fn run(message: RawMessage) -> CustomerQuery {
        let prompt = format!("Customer message:\n{}", message.text);
        let reply = inference_llm::infer(SYSTEM, &prompt, "classify");
        let (intent, entities, question) = parse_reply(&reply, &message.text);

        CustomerQuery {
            intent,
            entities,
            question,
        }
    }
}

export!(Node);
